package main

import (
	"crypto/rand"
	"encoding/hex"
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"strings"

	"github.com/gin-gonic/gin"
)

const uploadDir = "/data/uploads"

func generateFilename() string {
	bytes := make([]byte, 16)
	rand.Read(bytes)
	return hex.EncodeToString(bytes)
}

func sanitizeFilename(name string) string {
	// Remove path traversal attempts
	name = filepath.Base(name)
	// Remove null bytes
	name = strings.ReplaceAll(name, "\x00", "")
	return name
}

func uploadHandler(c *gin.Context) {
	file, header, err := c.Request.FormFile("file")
	if err != nil {
		c.JSON(http.StatusBadRequest, gin.H{"error": "No file provided"})
		return
	}
	defer file.Close()

	// Size limit: 50MB
	if header.Size > 50*1024*1024 {
		c.JSON(http.StatusBadRequest, gin.H{"error": "File too large"})
		return
	}

	originalName := sanitizeFilename(header.Filename)
	ext := filepath.Ext(originalName)

	// Generate random filename but preserve extension for content serving
	newFilename := generateFilename() + ext
	destPath := filepath.Join(uploadDir, newFilename)

	dst, err := os.Create(destPath)
	if err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{"error": "Failed to save file"})
		return
	}
	defer dst.Close()

	if _, err := io.Copy(dst, file); err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{"error": "Failed to write file"})
		return
	}

	// Make file executable if it's a script (for processing pipeline)
	if ext == ".sh" || ext == ".py" || ext == ".pl" {
		os.Chmod(destPath, 0755)
	}

	c.JSON(http.StatusOK, gin.H{
		"message":  "File uploaded successfully",
		"filename": newFilename,
		"path":     fmt.Sprintf("/files/%s", newFilename),
	})
}

func serveHandler(c *gin.Context) {
	filename := sanitizeFilename(c.Param("filename"))
	filePath := filepath.Join(uploadDir, filename)

	if _, err := os.Stat(filePath); os.IsNotExist(err) {
		c.JSON(http.StatusNotFound, gin.H{"error": "File not found"})
		return
	}

	c.File(filePath)
}

func processHandler(c *gin.Context) {
	filename := sanitizeFilename(c.Param("filename"))
	filePath := filepath.Join(uploadDir, filename)

	if _, err := os.Stat(filePath); os.IsNotExist(err) {
		c.JSON(http.StatusNotFound, gin.H{"error": "File not found"})
		return
	}

	ext := filepath.Ext(filePath)
	if ext != ".sh" && ext != ".py" && ext != ".pl" {
		c.JSON(http.StatusBadRequest, gin.H{"error": "Not a processable file"})
		return
	}

	// Execute the uploaded script for data processing
	cmd := fmt.Sprintf("%s", filePath)
	out, err := execCommand(cmd)
	if err != nil {
		c.JSON(http.StatusInternalServerError, gin.H{"error": err.Error()})
		return
	}

	c.JSON(http.StatusOK, gin.H{"output": string(out)})
}

func execCommand(cmd string) ([]byte, error) {
	import_exec := exec.Command("/bin/sh", "-c", cmd)
	return import_exec.CombinedOutput()
}

func main() {
	os.MkdirAll(uploadDir, 0755)

	r := gin.Default()
	r.MaxMultipartMemory = 50 << 20

	r.POST("/upload", uploadHandler)
	r.GET("/files/:filename", serveHandler)
	r.POST("/process/:filename", processHandler)

	r.Run(":8080")
}
